mapper.select:
SELECT * FROM artworks

    
        AND category = #{category}
    
    
        AND medium = #{medium}
    
    
        AND orientation = #{orientation}
    
    
        AND dominant_color = #{dominantColor}
    
    
        AND price >= #{minPrice}
    
    
        AND price <= #{maxPrice}
    


    ORDER BY price ASC
    ORDER BY price DESC
    ORDER BY created_at DESC
    ORDER BY id ASC

LIMIT #{limit} OFFSET #{offset}
